 Need(state.Commit(result)&&state.Index==1&&state.PreferredColor==color&&state.Results.Single().SelectedColor==color&&state.Phase=="paused","Valid color failed continuation");state.Validate();
 var reloaded=Copy(state);reloaded.Validate();Need(reloaded.PreferredColor==color&&reloaded.Results.Single().SelectedColor==color&&reloaded.Schema==1,"Persisted custom color/schema changed");
 Need(!state.Commit(result)&&state.Index==1,"Same result token committed twice");
