 var malformed=Session();malformed.Index=1;malformed.Phase="paused";malformed.Results=[new(){Token=Guid.NewGuid().ToString("N"),Completed=true,Fruits=30,SelectedColor=invalid}];Reject(()=>malformed.Validate());
}
